const fs = require("fs");
const path = require("path");

const discord = require("discord.js");
const ObjectDetection = require('../../util/object-detection');
const TempFolder = require('../../util/temp-folder');
const { createCanvas, loadImage } = require('canvas');

class Command {
    constructor() {
        this.name = "where";
        this.description = "Shows where items are in an image.";
        this.attributes = {
            unlisted: false,
            lockedToCommands: true,
            permission: 0,
        };

        this.alias = ["whereis"];

        this.example = [
            { text: "{{prefix}}where main subject, head, eye, mouth" },
            { text: "{{prefix}}where the asynchronous operation" },
        ];
    }

    async handle(message, args, util) {
        const [imageBuffer] = await util.getInputImagesForCommand(message);
        if (!imageBuffer) return;
        const realArgs = args.join(" ").split(",").map(argument => argument.trim()).filter(argument => !!argument);
        if (!realArgs[0]) return message.reply("What the fuck do you want me to look for");
        
        // actually start doing stuff
        const jobName = TempFolder.makeTempName("where");
        const temporaryFolder = new TempFolder(jobName);
        await temporaryFolder.createAndDestroy(async (tempDir) => {
            // resize the image (we reuse this canvas for later)
            const resizedHeight = 1024;
            const image = await loadImage(imageBuffer);
            const aspectRatio = image.width / image.height;
            const resizedWidth = Math.round(resizedHeight * aspectRatio);
            if (resizedWidth > 8192) throw new Error("Image is wider than 4x the height");
            
            const canvas = createCanvas(resizedWidth, resizedHeight);
            const ctx = canvas.getContext("2d");
            ctx.drawImage(image, 0, 0, canvas.width, canvas.height);

            // download
            const imagePath = path.join(tempDir, "image.png");
            await new Promise((resolve, reject) => {
                fs.writeFile(imagePath, canvas.toBuffer("image/png"), (err) => {
                    if (err) return reject(err);
                    resolve();
                });
            });

            // look at the image
            await message.channel.sendTyping();
            const objects = await ObjectDetection.predict(imagePath, realArgs);
            
            // draw the boxes
            const fontSize = 18;
            const fontHeight = fontSize + 8;
            ctx.font = `${fontSize}px Arial`;
            for (const objectName in objects) {
                const boxes = objects[objectName];
                for (const box of boxes) {
                    const text = `${objectName}${box.term !== objectName ? ` (${box.term})` : ""}`;
                    const boxColor = box.score * 200; // 0 = red (not confident at all), 0.5 = green (pretty confident), 1 = blue (ULTRA confident) 
                    const textMeasurements = ctx.measureText(text);

                    const width = box.box[2] - box.box[0];
                    const height = box.box[3] - box.box[1];

                    // box
                    const strokeWidth = Math.min(4, width / 2, height / 2);
                    ctx.fillStyle = `hsl(${boxColor}, 100%, 50%)`;
                    ctx.fillRect(box.box[0], box.box[1], width, strokeWidth);
                    ctx.fillRect(box.box[0], box.box[1], strokeWidth, height);
                    ctx.fillRect(box.box[0] + (width - strokeWidth), box.box[1], strokeWidth, height);
                    ctx.fillRect(box.box[0], box.box[1] + (height - strokeWidth), width, strokeWidth);

                    // label (we dont care if this escapes the box)
                    ctx.fillRect(box.box[0], box.box[1], textMeasurements.width, fontHeight);

                    // label text
                    ctx.fillStyle = "black";
                    ctx.fillText(text, box.box[0], box.box[1] + fontSize);
                }
            }

            const dataBuffer = Buffer.from(JSON.stringify(objects, null, 4), "utf8");
            const dataAttachment = new discord.MessageAttachment(dataBuffer, "objects.json");
            const drawnBuffer = canvas.toBuffer("image/png");
            message.reply({
                content: `Generated by <@${message.author.id}>`,
                files: [drawnBuffer, dataAttachment],
                allowedMentions: {
                    parse: [],
                    users: [],
                    roles: [],
                    repliedUser: false
                }
            });
        });
    }
    async invoke(message, args, util) {
        const canDo = util.request("heavyExternalStuff");
        if (!canDo) return message.reply("disabled (im probably playing a game)");

        await this.handle(message, args, util);
    }
}

// needs to do new Command() in index.js because typing static every time STINKS!
module.exports = Command;